REVOKE EXECUTE ON FUNCTION public.finish_analysis(uuid,boolean) FROM authenticated;
CREATE FUNCTION public.settle_analysis_usage(_user uuid,_analysis uuid,_success boolean) RETURNS void LANGUAGE plpgsql SECURITY DEFINER SET search_path=public AS $$
BEGIN
 UPDATE public.usage_events SET state=CASE WHEN _success THEN 'completed' ELSE 'released' END WHERE user_id=_user AND operation_id=_analysis AND state='reserved';
END $$;
REVOKE ALL ON FUNCTION public.settle_analysis_usage(uuid,uuid,boolean) FROM PUBLIC;
GRANT EXECUTE ON FUNCTION public.settle_analysis_usage(uuid,uuid,boolean) TO service_role;
CREATE FUNCTION public.guard_analysis_result() RETURNS trigger LANGUAGE plpgsql SECURITY DEFINER SET search_path=public AS $$
BEGIN
 IF auth.uid() IS NOT NULL THEN
 IF TG_OP='INSERT' THEN
  IF NEW.status='completed' OR NEW.analysis IS NOT NULL OR NEW.extracted_data IS NOT NULL OR NEW.risk_score IS NOT NULL THEN RAISE EXCEPTION 'Financial results must be generated by the server'; END IF;
 ELSE
  IF NEW.analysis IS DISTINCT FROM OLD.analysis OR NEW.extracted_data IS DISTINCT FROM OLD.extracted_data OR NEW.risk_score IS DISTINCT FROM OLD.risk_score OR (NEW.status='completed' AND OLD.status<>'completed') THEN RAISE EXCEPTION 'Financial results must be generated by the server'; END IF;
 END IF;
 END IF;
 RETURN NEW;
END $$;
CREATE TRIGGER trusted_analysis_result BEFORE INSERT OR UPDATE ON public.analyses FOR EACH ROW EXECUTE FUNCTION public.guard_analysis_result();
CREATE FUNCTION public.admin_save_plan(_plan jsonb) RETURNS void LANGUAGE plpgsql SECURITY DEFINER SET search_path=public AS $$
BEGIN
 IF NOT public.session_active() OR NOT public.has_role(auth.uid(),'super_admin') THEN RAISE EXCEPTION 'Super Administrator access required'; END IF;
 IF (_plan->>'id') NOT IN ('free','professional','business') THEN RAISE EXCEPTION 'Invalid plan'; END IF;
 IF COALESCE((_plan->>'analysis_limit')::integer,0)<0 OR COALESCE((_plan->>'report_limit')::integer,0)<0 OR COALESCE((_plan->>'company_limit')::integer,1)<1 OR COALESCE((_plan->>'price_amount')::numeric,0)<0 THEN RAISE EXCEPTION 'Invalid plan allowances'; END IF;
 INSERT INTO public.subscription_plans(id,name,price_amount,currency,analysis_limit,report_limit,company_limit,features,active) VALUES(_plan->>'id',_plan->>'name',(_plan->>'price_amount')::numeric,upper(_plan->>'currency'),(_plan->>'analysis_limit')::integer,(_plan->>'report_limit')::integer,(_plan->>'company_limit')::integer,COALESCE(_plan->'features','{}'::jsonb),COALESCE((_plan->>'active')::boolean,false)) ON CONFLICT(id) DO UPDATE SET name=EXCLUDED.name,price_amount=EXCLUDED.price_amount,currency=EXCLUDED.currency,analysis_limit=EXCLUDED.analysis_limit,report_limit=EXCLUDED.report_limit,company_limit=EXCLUDED.company_limit,features=EXCLUDED.features,active=EXCLUDED.active,updated_at=now();
 INSERT INTO public.admin_audit(actor_id,action,target_id,details) VALUES(auth.uid(),'configure_plan',_plan->>'id',_plan);
END $$;
REVOKE ALL ON FUNCTION public.admin_save_plan(jsonb) FROM PUBLIC;
GRANT EXECUTE ON FUNCTION public.admin_save_plan(jsonb) TO authenticated;